import 'svelte/internal/disclose-version';
import * as $ from 'svelte/internal/client';

var root = $.from_html(`<span class="cell"> </span>`);
var root_1 = $.from_html(`<tr><td> </td><td><button> </button></td><td> </td></tr>`);
var root_2 = $.from_html(`<main><p data-count=""> </p><label>Search<input aria-label="Search"/></label><output> </output><section class="dashboard"></section><table><tbody></tbody></table></main>`);

export default function App($$anchor, $$props) {
	$.push($$props, true);

	var main = root_2();
	var p = $.child(main);
	var text = $.only_child(p, true);
	var label = $.sibling(p);
	var input = $.sibling($.child(label));

	$.remove_input_defaults(input);
	$.reset(label);

	var output = $.sibling(label);
	var text_1 = $.only_child(output, true);
	var section = $.sibling(output);

	$.each(section, 21, () => $$props.state.cells, $.index, ($$anchor, v) => {
		var span = root();
		var text_2 = $.only_child(span, true);

		$.template_effect(() => $.set_text(text_2, $.get(v)));
		$.append($$anchor, span);
	});

	$.reset(section);

	var table = $.sibling(section);
	var tbody = $.child(table);

	$.each(tbody, 21, () => $$props.state.rows, (r) => r.id, ($$anchor, r) => {
		var tr = root_1();
		var td = $.child(tr);
		var text_3 = $.only_child(td, true);
		var td_1 = $.sibling(td);
		var button = $.child(td_1);
		var text_4 = $.only_child(button, true);

		$.reset(td_1);

		var td_2 = $.sibling(td_1);
		var text_5 = $.only_child(td_2, true);

		$.reset(tr);

		$.template_effect(() => {
			$.set_attribute(tr, 'data-id', $.get(r).id);
			$.set_class(tr, 1, $.clsx($.get(r).id === $$props.state.selected ? 'selected' : ''));
			$.set_text(text_3, $.get(r).id);
			$.set_text(text_4, $.get(r).label);
			$.set_text(text_5, $.get(r).value);
		});

		$.delegated('click', button, () => $$props.dispatch('select', $.get(r).id));
		$.append($$anchor, tr);
	});

	$.reset(tbody);
	$.reset(table);
	$.reset(main);

	$.template_effect(() => {
		$.set_text(text, $$props.state.rows.length);
		$.set_value(input, $$props.state.text);
		$.set_text(text_1, $$props.state.text);
	});

	$.delegated('input', input, (e) => $$props.dispatch('text', e.target.value));
	$.append($$anchor, main);
	$.pop();
}

$.delegate(['input', 'click']);